<?php
require_once __DIR__ . '/../app/application.php';if(!can('reports.view')&&!can('reports.financial')){http_response_code(403);exit('Not authorized.');}$agencyId=(int)($_GET['agency_id']??0);requireAgencyAccess($agencyId);$from=validDateValue($_GET['from']??'')?$_GET['from']:date('Y-m-01');$to=validDateValue($_GET['to']??'')?$_GET['to']:date('Y-m-t');$rows=dbFetchAll("SELECT v.registration_number,v.brand,v.model,COUNT(DISTINCT r.id) rentals,COALESCE(SUM(p.amount),0) revenue FROM vehicles v LEFT JOIN reservations r ON r.vehicle_id=v.id LEFT JOIN payments p ON p.reservation_id=r.id AND p.status='paid' AND DATE(p.paid_at) BETWEEN :from AND :to WHERE v.agency_id=:agency AND v.archived_at IS NULL GROUP BY v.id ORDER BY revenue DESC",['from'=>$from,'to'=>$to,'agency'=>$agencyId]);header('Content-Type: text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="vehicle-revenue-'.$from.'-'.$to.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','wb');fputcsv($out,['Registration','Brand','Model','Rentals','Revenue','Currency']);foreach($rows as $row){$safe=array_map(function($value){$value=(string)$value;return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;},[$row['registration_number'],$row['brand'],$row['model'],$row['rentals'],$row['revenue'],appConfig('currency')]);fputcsv($out,$safe);}fclose($out);exit;
